# Loads the four Android release-signing variables from .secrets/release-signing.env
# and, with -ThenBuild, runs tools/build_android_release.ps1 in the same process so
# the variables actually reach Gradle.
#
# Why a loader instead of exporting them by hand every session: the values are long
# random strings, and a typo shows up only as an opaque Gradle signing error. The
# file is git-ignored and generated by tools/gen_release_keystore.py.
#
# Everything here is ASCII on purpose: Windows PowerShell 5.1 reads BOM-less files
# as ANSI, so non-ASCII strings would come out garbled.
#
# Usage:
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\load_signing_env.ps1 -ThenBuild
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\load_signing_env.ps1 -ThenBuild -OutputRoot D:\out

[CmdletBinding()]
param(
    [string]$EnvFile,
    [switch]$ThenBuild,
    [string]$OutputRoot,
    [string]$AndroidSdkRoot
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$repoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
if (-not $EnvFile) {
    $EnvFile = Join-Path $repoRoot ".secrets\release-signing.env"
}
if (-not (Test-Path -LiteralPath $EnvFile -PathType Leaf)) {
    throw "Signing env file not found: $EnvFile. Generate it with: python tools/gen_release_keystore.py"
}

$names = @(
    "FNAUDIO_RELEASE_STORE_FILE",
    "FNAUDIO_RELEASE_STORE_PASSWORD",
    "FNAUDIO_RELEASE_KEY_ALIAS",
    "FNAUDIO_RELEASE_KEY_PASSWORD"
)
$seen = @{}
foreach ($line in Get-Content -LiteralPath $EnvFile -Encoding UTF8) {
    $trimmed = $line.Trim()
    if (-not $trimmed -or $trimmed.StartsWith("#")) { continue }
    $index = $trimmed.IndexOf("=")
    if ($index -lt 1) { continue }
    $name = $trimmed.Substring(0, $index).Trim()
    $value = $trimmed.Substring($index + 1).Trim()
    if ($names -notcontains $name) { continue }
    [Environment]::SetEnvironmentVariable($name, $value, "Process")
    $seen[$name] = $true
}

$missing = @($names | Where-Object { -not $seen.ContainsKey($_) })
if ($missing.Count -gt 0) {
    throw "Signing env file is incomplete; missing: $($missing -join ', ')"
}

$storeFile = [Environment]::GetEnvironmentVariable("FNAUDIO_RELEASE_STORE_FILE")
$keyAlias = [Environment]::GetEnvironmentVariable("FNAUDIO_RELEASE_KEY_ALIAS")
if (-not (Test-Path -LiteralPath $storeFile -PathType Leaf)) {
    throw "Keystore named by FNAUDIO_RELEASE_STORE_FILE does not exist: $storeFile"
}
Write-Host "signing material loaded: $storeFile (alias $keyAlias)"

if (-not $ThenBuild) {
    Write-Host "Variables set for this process only. Re-run with -ThenBuild to build the release APK."
    exit 0
}

$arguments = @{}
if ($OutputRoot) { $arguments["OutputRoot"] = $OutputRoot }
if ($AndroidSdkRoot) { $arguments["AndroidSdkRoot"] = $AndroidSdkRoot }
& (Join-Path $PSScriptRoot "build_android_release.ps1") @arguments
exit $LASTEXITCODE
